{
  "table": {
    "name": "badges",
    "purpose": "One row per badge awarded to a user on a Stack Exchange-style Q&A site (Stack Exchange 'Badges' export). Each row records a single badge (name) granted to a specific user at a specific date/time. A user can earn the same badge multiple times (e.g. tag-based badges)."
  },
  "columns": {
    "col_001": {
      "role": "identifier",
      "name": "badge_id",
      "description": "Primary key. Unique surrogate identifier for each badge award row. The many 'referenced_by' joins are spurious: other tables contain user/post ids that happen to fall in the same numeric range, not references to badge ids.",
      "status": "resolved"
    },
    "col_002": {
      "role": "foreign_key",
      "name": "user_id",
      "description": "Id of the user who received the badge. References users.col_001 (many badges per user; ~25k distinct users among ~80k badges). The join to postHistory.col_001 is coincidental (both are user ids).",
      "status": "resolved"
    },
    "col_003": {
      "role": "category",
      "name": "badge_name",
      "description": "Name of the badge awarded. Mostly standard Stack Exchange badge names (Student, Supporter, Editor, Scholar, Teacher, Autobiographer, Analytical, ...), plus tag-based badges whose name is a tag (e.g. 'correlation', 'pca', 'modeling', 'nonparametric', 'Outspoken') earned for activity in that tag.",
      "status": "resolved"
    },
    "col_004": {
      "role": "date",
      "name": "awarded_at",
      "description": "Timestamp (date and time) when the badge was awarded, ranging from 2010-07-19 to 2014-09-14.",
      "status": "resolved"
    }
  }
}
